content.query:
// Open Critical + High alerts from all sources
union isfuzzy=true SecurityAlert
| where TimeGenerated {TimeRange}
| where AlertSeverity in ("Critical", "High")
| where Status !in ("Resolved", "Closed")
| summarize ['Open Critical/High Alerts']=count()

// CISA KEV CVEs present in MDE device inventory
// Requires CISA-KEV watchlist with cveID as SearchKey
let KEV = union isfuzzy=true (_GetWatchlist('CISA-KEV') | project cveID=SearchKey);
union isfuzzy=true DeviceTvmSoftwareVulnerabilities
| where TimeGenerated {TimeRange}
| where isnotempty(CveId)
| where CveId in (KEV)
| summarize ['KEV Matches']=dcount(CveId)

// VIB Q1 2026 priority CVEs detected in MDE device inventory
// Source: UoN Vulnerability Intelligence Brief Q1 2026, Section 3.1
let PriorityCVEs = dynamic(["CVE-2026-20131","CVE-2026-1731","CVE-2026-1281","CVE-2026-1340","CVE-2026-24858","CVE-2026-21858","CVE-2025-61882","CVE-2025-14847"]);
union isfuzzy=true DeviceTvmSoftwareVulnerabilities
| where TimeGenerated {TimeRange}
| where CveId in (PriorityCVEs)
| summarize ['VIB Priority CVEs Present']=dcount(CveId)

// Medium/High risk sign-ins from Entra ID
union isfuzzy=true SigninLogs
| where TimeGenerated {TimeRange}
| where RiskLevelDuringSignIn in ("high", "medium")
| summarize ['Risky Sign-ins']=count()

// Mean time to resolve closed incidents
union isfuzzy=true SecurityIncident
| where ClosedTime {TimeRange}
| where Status == "Closed"
| extend MTTRHours = datetime_diff('minute', ClosedTime, CreatedTime) / 60.0
| summarize ['Avg MTTR (hrs)']=round(avg(MTTRHours), 1)

// Alert severity breakdown across all connected sources
union isfuzzy=true SecurityAlert
| where TimeGenerated {TimeRange}
| summarize Count=count() by AlertSeverity
| sort by Count desc

// Alert volume trend by severity
union isfuzzy=true SecurityAlert
| where TimeGenerated {TimeRange}
| summarize Count=count() by bin(TimeGenerated, 1d), AlertSeverity
| sort by TimeGenerated asc

// MDE onboarding coverage — are all devices reporting?
union isfuzzy=true DeviceInfo
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by DeviceId
| summarize Count=count() by OnboardingStatus
| sort by Count desc

// KEV exposure by software vendor
let KEV = union isfuzzy=true (_GetWatchlist('CISA-KEV') | project cveID=SearchKey, vendorProject=column_ifexists('vendorProject','Unknown'));
union isfuzzy=true DeviceTvmSoftwareVulnerabilities
| where TimeGenerated {TimeRange}
| where isnotempty(CveId)
| join kind=inner KEV on $left.CveId == $right.cveID
| summarize CVECount=dcount(CveId) by vendorProject
| sort by CVECount desc
| take 15

// CVE severity distribution across all MDE-managed devices
union isfuzzy=true DeviceTvmSoftwareVulnerabilities
| where TimeGenerated {TimeRange}
| summarize DeviceCount=dcount(DeviceId) by VulnerabilitySeverityLevel
| sort by DeviceCount desc

// KEV dwell time — days since each matched CVE was added to CISA KEV list
let KEV = union isfuzzy=true (_GetWatchlist('CISA-KEV')
    | project cveID=SearchKey,
              vendorProject = column_ifexists('vendorProject', 'Unknown'),
              dateAdded     = column_ifexists('dateAdded', ''));
union isfuzzy=true DeviceTvmSoftwareVulnerabilities
| where TimeGenerated {TimeRange}
| join kind=inner KEV on $left.CveId == $right.cveID
| extend DwellDays = iff(isnotempty(dateAdded), datetime_diff('day', now(), todatetime(dateAdded)), int(null))
| summarize DwellDays=max(DwellDays), AffectedDevices=dcount(DeviceId) by CveId, vendorProject
| sort by DwellDays desc
| take 25

// Risky sign-ins detected by Entra ID Identity Protection
union isfuzzy=true SigninLogs
| where TimeGenerated {TimeRange}
| where RiskLevelDuringSignIn in ("high", "medium")
| summarize ['Risky Sign-ins']=count()

// Failed MFA attempts — excludes expected interrupts (50140 = stay signed in, 50126 = wrong credential)
union isfuzzy=true SigninLogs
| where TimeGenerated {TimeRange}
| where AuthenticationRequirement == "multiFactorAuthentication"
| where ResultType !in ("0", "50140", "50074", "50005")
| summarize ['Failed MFA Attempts']=count()

// Accounts at risk of compromise — risky users from Entra
union isfuzzy=true SigninLogs
| where TimeGenerated {TimeRange}
| where RiskLevelDuringSignIn in ("high", "medium")
| summarize ['Accounts with Risky Sign-ins']=dcount(UserPrincipalName)

// ShinyHunters pattern — admin-initiated credential reset followed by sign-in within 60 minutes
// VIB Q1 2026 Section 5.2: ShinyHunters bypassed MFA by calling help desk to reset credentials
// A reset + immediate login from a new IP is the clearest indicator of this technique
let Resets = union isfuzzy=true AuditLogs
    | where TimeGenerated {TimeRange}
    | where OperationName == "Reset password (by admin)"
    | extend TargetUser = tostring(TargetResources[0].userPrincipalName)
    | project ResetTime=TimeGenerated, TargetUser;
union isfuzzy=true SigninLogs
| where TimeGenerated {TimeRange}
| where ResultType == "0"
| join kind=inner Resets on $left.UserPrincipalName == $right.TargetUser
| where TimeGenerated >= ResetTime
| where datetime_diff('minute', TimeGenerated, ResetTime) <= 60
| project TimeGenerated, UserPrincipalName, ResetTime, MinutesAfterReset=datetime_diff('minute', TimeGenerated, ResetTime), AppDisplayName, IPAddress, Country=tostring(LocationDetails.countryOrRegion), AuthenticationRequirement
| sort by MinutesAfterReset asc

// Incident count by severity — current status only
union isfuzzy=true SecurityIncident
| where CreatedTime {TimeRange}
| summarize arg_max(LastModifiedTime, *) by IncidentNumber
| summarize Count=count() by Severity, Status
| sort by Severity asc

// Alert source breakdown — which tools are generating alerts
union isfuzzy=true SecurityAlert
| where TimeGenerated {TimeRange}
| summarize Count=count() by ProviderName
| sort by Count desc
| take 15

// Total blocked/rejected email threats from Mimecast and Defender for O365
union isfuzzy=true
    (CommonSecurityLog
     | where TimeGenerated {TimeRange}
     | where DeviceVendor =~ "Mimecast"
     | where DeviceAction has_any ("Block", "Reject", "Hold", "block", "reject", "hold")),
    (MimecastSEGEvent_CL
     | where TimeGenerated {TimeRange}
     | where column_ifexists('action_s','') has_any ("Block", "Reject", "Hold")),
    (EmailEvents
     | where TimeGenerated {TimeRange}
     | where DeliveryAction in ("Blocked", "Replaced"))
| summarize ['Blocked Threats']=count()

// Phishing-specific detections
union isfuzzy=true
    (CommonSecurityLog
     | where TimeGenerated {TimeRange}
     | where DeviceVendor =~ "Mimecast"
     | where DeviceEventClassID has_any ("phish", "Phish", "spam", "Spam")),
    (MimecastSEGEvent_CL
     | where TimeGenerated {TimeRange}
     | where column_ifexists('type_s','') has_any ("phish", "spam")),
    (EmailEvents
     | where TimeGenerated {TimeRange}
     | where ThreatTypes has "Phish")
| summarize ['Phishing Detections']=count()

// Malware detections in email
union isfuzzy=true
    (CommonSecurityLog
     | where TimeGenerated {TimeRange}
     | where DeviceVendor =~ "Mimecast"
     | where DeviceEventClassID has_any ("malware", "Malware", "virus", "Virus")),
    (MimecastSEGEvent_CL
     | where TimeGenerated {TimeRange}
     | where column_ifexists('type_s','') has_any ("malware", "virus")),
    (EmailEvents
     | where TimeGenerated {TimeRange}
     | where ThreatTypes has "Malware")
| summarize ['Malware Detections']=count()

// Weekly alert volume — all sources
union isfuzzy=true SecurityAlert
| where TimeGenerated {TimeRange}
| summarize Alerts=count() by bin(TimeGenerated, 7d)
| sort by TimeGenerated asc

// Weekly risky sign-in trend — identity risk trajectory
union isfuzzy=true SigninLogs
| where TimeGenerated {TimeRange}
| where RiskLevelDuringSignIn in ("high", "medium")
| summarize RiskySignIns=count() by bin(TimeGenerated, 7d)
| sort by TimeGenerated asc

// GuardDuty high and critical severity findings
union isfuzzy=true AWSGuardDuty
| where TimeGenerated {TimeRange}
| where Severity >= 7.0
| summarize ['GuardDuty High/Critical']=count()

// Root account usage — should be zero in a well-governed environment
union isfuzzy=true AWSCloudTrail
| where TimeGenerated {TimeRange}
| where UserIdentityType == "Root"
| summarize ['Root Account Events']=count()

// Failed API calls — high volume may indicate credential stuffing or misconfigured services
union isfuzzy=true AWSCloudTrail
| where TimeGenerated {TimeRange}
| where isnotempty(ErrorCode)
| summarize ['Failed API Calls']=count()

// Distinct AWS accounts seen in GuardDuty findings
union isfuzzy=true AWSGuardDuty
| where TimeGenerated {TimeRange}
| summarize ['AWS Accounts in Scope']=dcount(AccountId)

// GuardDuty finding type breakdown — what categories of threats are being detected
union isfuzzy=true AWSGuardDuty
| where TimeGenerated {TimeRange}
| extend Category = tostring(split(Type, ':')[0])
| summarize Count=count() by Category
| sort by Count desc

// Step 4a: CISA-KEV watchlist
union isfuzzy=true _GetWatchlist('CISA-KEV')
| summarize TotalEntries=count(), Latest=max(column_ifexists('dateAdded',''))
